    static byte propertyOf(int codePoint) {
        int low = 0;
        int high = STARTS.length - 1;
        while (low <= high) {
            int middle = (low + high) >>> 1;
            if (STARTS[middle] <= codePoint) {
                low = middle + 1;
            } else {
                high = middle - 1;
            }
        }
        return VALUES[Math.max(0, high)];
    }

    static boolean isExtendedPictographic(int codePoint) {
        int low = 0;
        int high = EXTENDED_PICTOGRAPHIC_RANGES.length / 2 - 1;
        while (low <= high) {
            int middle = (low + high) >>> 1;
            int start = EXTENDED_PICTOGRAPHIC_RANGES[middle * 2];
            int rangeEnd = EXTENDED_PICTOGRAPHIC_RANGES[middle * 2 + 1];
            if (codePoint < start) {
                high = middle - 1;
            } else if (codePoint > rangeEnd) {
                low = middle + 1;
            } else {
                return true;
            }
        }
        return false;
    }

